import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import {NativeHomeSession} from '../session.mjs';
const root=new URL('../',import.meta.url),c=JSON.parse(fs.readFileSync(new URL('contract.json',root))),masks=Object.fromEntries(Object.entries(c.masks).map(([k,v])=>[k,new Uint8Array(fs.readFileSync(new URL(v.path,root)))]));const make=()=>new NativeHomeSession({contract:c,homeId:'coastal',masks});
test('original support all932503 centres retained, no new double erosion',()=>{let old=0;for(let i=0;i<masks.exterior.length;i++){if(masks.originalExterior[i]){old++;assert.equal(masks.exterior[i],1)}assert.equal(masks.exterior[i],masks.originalExterior[i]||masks.newCoastal[i])}assert.equal(old,932503)});
test('west support edge x1289 to1288 produces scope hold not collision wall and remains recoverable',()=>{const s=make();s.foot=[1289,1375];const before=s.foot.slice();assert.equal(s.safe('exterior',s.foot),true);assert.deepEqual(s.move('left'),{ok:false,reason:'OUTSIDE_VERIFIED_SCOPE',physicalWall:false});assert.deepEqual(s.foot,before);assert.equal(s.moving,false);assert.equal(s.move('right').ok,true);assert.equal(s.error,null)});
test('unsupported source never teleports into new support',()=>{const s=make();s.foot=[1288,1375];assert.equal(s.move('right').reason,'EXISTING_SUPPORT_BLOCKED');assert.deepEqual(s.foot,[1288,1375])});
test('original destination always stays accessible even where new region ends',()=>{const s=make();s.foot=[1572,1440];for(let i=0;i<30;i++)assert.equal(s.move('down').ok,true);assert.deepEqual(s.foot,[1572,1470]);assert.equal(s.error,null)});
test('coastal source failure keeps current home ownership and explicit scope supports only two remaining unassigned',async()=>{const s=new NativeHomeSession({contract:c,homeId:'upper',masks,loadScene:async()=>({sha256:'bad'})});s.foot=[1572,1375];s.face('up');s.setDoorState('OPEN','coastal');assert.equal((await s.action()).reason,'TARGET_SOURCE_PIN_MISMATCH');assert.equal(s.homeId,'upper');assert.equal(s.scene,'exterior');assert.deepEqual(c.unassigned.map(x=>x.id),['garden_home_hanok','keeper_home'])});

test('malformed or out-of-world source remains rejected before scope helper',()=>{for(const foot of [[-1,1375],[1289.5,1375],[5120,1375],[1289,-1],[NaN,1375]]){const s=make();s.foot=foot;assert.equal(s.move('right').reason,'EXISTING_SUPPORT_BLOCKED')}});
